import("stdfaust.lib");

// Warm and muffled synth effect
cutoff = hslider("Cutoff [unit:Hz]", 1000, 20, 20000, 1) : si.smoo;
q = hslider("Resonance", 1.0, 0.5, 20, 0.01) : si.smoo;
delayTime = hslider("Delay Time [unit:ms]", 300, 1, 2000, 1) : si.smoo : *(ma.SR/1000.0) : min(192000-1) : max(1);
feedback = hslider("Feedback", 0.4, 0, 0.95, 0.01) : si.smoo;
mix = hslider("Dry/Wet", 0.5, 0, 1, 0.01) : si.smoo;

// Low-pass filter
lp = fi.resonlp(cutoff, q, 1.0);

// Delay
delay = de.fdelay(192000, delayTime);

// Feedback loop
feedbackLoop = delay : *(feedback) : ~;

// Muffled sound effect
muffled = (lp : feedbackLoop) : *(mix) + _ : *(1 - mix);

// Process
process = muffled, muffled;

import("stdfaust.lib");
MAXD  = 192000;
dtime = hslider("Delay Time [unit:ms]", 300, 1, 2000, 1) : si.smoo
        : *(ma.SR/1000.0) : min(MAXD-1) : max(1);
fb    = hslider("Feedback", 0.4, 0, 0.95, 0.01);
mix   = hslider("Dry/Wet", 0.5, 0, 1, 0.01) : si.smoo;
process = _,_ <: dry, wet :> _,_
with {
  cross(fbL, fbR, inL, inR) = inL + fbR*fb, inR + fbL*fb;
  dry = par(i, 2, _ * (1 - mix));
  wet = (cross ~ (de.fdelay(MAXD, dtime), de.fdelay(MAXD, dtime))) : par(i, 2, _ * mix);
  wet = wet : *(mix : -,1) : ef.dryWetMixer(mix, wet);
};

