import("stdfaust.lib");

freq = hslider("Frequency [unit:Hz]", 400, 40, 2000, 1) : si.smoo;
decay = hslider("Decay Time [unit:ms]", 100, 10, 1000, 1) : si.smoo;
damp = hslider("Damping", 0.5, 0, 1, 0.01) : si.smoo;
trigger = hslider("Trigger", 0, 0, 1, 0.01);

MAXD = 192000;
delayTime = freq : ba.sec2samp : min(MAXD-1) : max(1);
feedback = decay : ba.sec2samp : min(MAXD-1) : max(1);
damping = damp * 0.999;

delayLine(x) = de.fdelay(MAXD, delayTime, x);
feedbackLine(x) = delayLine(x) * feedback * damping;

process = trigger : select2(trigger, _, feedbackLine), _;
with {
  feedbackLine = feedbackLine : delayLine;
};

import("stdfaust.lib");

fSamplingFreq = ma.SR;
stringLength = hslider("String Length [unit:s]", 0.1f, 0.01f, 0.5f, 0.01f) : si.smoo;
pluckPosition = hslider("Pluck Position", 0.5f, 0.0f, 1.0f, 0.01f) : si.smoo;
pluckAmplitude = hslider("Pluck Amplitude", 0.5f, 0.0f, 1.0f, 0.01f) : si.smoo;
decayTime = hslider("Decay Time [unit:s]", 0.1f, 0.01f, 1.0f, 0.01f) : si.smoo;

stringLengthSamples = stringLength * fSamplingFreq;
pluckPositionSamples = pluckPosition * stringLengthSamples;
decay = 1.0f / (fSamplingFreq * decayTime);

string = de.fdelay(stringLengthSamples, 0.0f, 0.0f);
pluck = de.fdelay(pluckPositionSamples, pluckAmplitude, 0.0f);

process = pluck : string : *(decay), pluck : string : *(decay);

